/* ❌ OLD WAY: Pages Router (pages/users.tsx) */
export default function Users({ users }) {
  return <div>{users.map(u => <p>{u.name}</p>)}</div>
}

// Special framework-specific function to fetch data
export async function getServerSideProps() {
  const res = await fetch('https://api/users')
  const users = await res.json()
  return { props: { users } }
}

/* ✅ NEW WAY: App Router (app/users/page.tsx) */
// Standard async React component! No special functions needed.
export default async function Users() {
  const res = await fetch('https://api/users')
  const users = await res.json()

  return <div>{users.map(u => <p>{u.name}</p>)}</div>
}
